Given two strings s and p, the task is to find the smallest substring in s that contains all characters of p, including duplicates. If no such substring exists, return "". If multiple substrings of the same length are found, return the one with the smallest starting index.Examples: Input: s = "timetopractice", p = "toc"Output: topracExplanation: "toprac" is the smallest substring in which "toc" can be found.Input: s = "zoomlazapzo", p = "oza"Output: apzoExplanation: "apzo" is the smallest substring in which "oza" can be found.Try It YourselfTable of Content[Naive Approach] By Generating all the Substrings - O(n^3) time and O(n) space:[Better Approach] By using Binary Search on Answer - O(n*log(n)) Time and O(1) Space:[Expected Approach] Using Window Sliding - O(n) Time and O(1) Space:[Naive Approach] By Generating all the Substrings - O(n^3) time and O(n) space:The very basic idea to solve this problem is that we can generate all possible substrings of the given string s and checking each substring to see if it contains all characters of string p. This checking can be done by a helper function that counts the frequency of each character in p equals with frequency of the chosen substring. If a substring contains all characters of the p, then its length is compared to the current minimum length and the smallest substring is updated accordingly. The process continues until all substrings have been checked.
            C++

    #include <climits>
#include <iostream>
#include <string>
using namespace std;

bool hasAllChars(string &sub, string &p) {
    int count[256] = {0};

    // Count the frequency of each 
    // character in the pattern
    for (char ch : p)
        count[ch]++;

    // For each character in the substring, 
    // decrement its count
    for (char ch : sub) {
        if (count[ch] > 0)
            count[ch]--;
    }

    // If all counts in the count array are zero,
    // the substring contains all characters of the pattern
    for (int i = 0; i < 256; i++) {
        if (count[i] > 0)
            return false;
    }

    return true;
}

// Function to find the smallest substring 
// containing all characters of the pattern
string minWindow(string &s, string &p) {
    int n = s.length();
    int minLen = INT_MAX;
    string res = "";

    // Generate all substrings 
    // of the given string
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            string sub = s.substr(i, j - i + 1);

            // Check if the substring contains 
            // all characters of the pattern
            if (hasAllChars(sub, p)) {
                int currLen = sub.length();

                // Update the result if the current
                // substring is smaller
                if (currLen < minLen) {
                    minLen = currLen;
                    res = sub;
                }
            }
        }
    }

    return res;
}

int main() {
    string s = "timetopractice";
    string p = "toc";

    string res = minWindow(s, p);

    if (!res.empty())
        cout << res << endl;
    else
        cout << "" << endl;

    return 0;
}


