[Better Approach] By using Binary Search on Answer - O(n*log(n)) Time and O(1) Space:The idea is to check if a window of a certain size "mid" is valid (contains all characters of the p string), then all windows of size greater than "mid" will also be valid. Similarly, if a window of size "mid" is not valid, then all windows of size smaller than "mid" will also not be valid. This property allows us to apply binary search effectively.Follow the steps below to solve the problem:Initialize low = 1 and high = string length. Denoting the minimum and maximum possible answer.For any value mid check if there is any substring of length mid in the string that contains all the characters of the P.If any such substring of length exists then store the starting index of that substring and update high to mid-1 and, check for substrings having lengths smaller than mid.Otherwise, if any such substring does not exist then update low to mid+1 and, check for substrings having lengths larger than mid.
            C++

    #include <iostream>
#include <string>
#include <climits>
#include <cstring>
using namespace std;

bool isValid(string &s, string &p, int mid, int &start){
    int count[256] = {0};

    int distinct = 0;

    // Count the frequency of each character in p
    for (char x : p){
        if (count[x] == 0)
            distinct++;
        count[x]++;
    }

    // Stores the number of characters in a substring of size
    // mid in s whose frequency is the same as the frequency in p
    int curr_count = 0;
    for (int i = 0; i < s.size(); i++){
        count[s[i]]--;
        if (count[s[i]] == 0){
            curr_count++;
        }

        if (i >= mid){
            count[s[i - mid]]++;
            if (count[s[i - mid]] == 1){
                curr_count--;
            }
        }

        if (i >= mid - 1){
            // Substring of length mid found which contains
            // all the characters of p
            if (curr_count == distinct){
                start = (i - mid) + 1;
                return true;
            }
        }
    }

    return false;
}

string minWindow(string s, string p){
    int m = s.length();
    int n = p.length();

    // If s is smaller than p, it's impossible
    if (m < n)
        return "-1";

    int minLength = INT_MAX;

    // Lower bound and Upper Bound for Binary Search
    // The smallest valid window size is n (size of p)
    int low = n, high = m;

    int idx = -1;

    while (low <= high){
        int mid = (low + high) / 2;
        int start;

        if (isValid(s, p, mid, start)){
            if (mid < minLength){
                minLength = mid;
                idx = start;
            }
            high = mid - 1;
        }
        else{
            low = mid + 1;
        }
    }

    if (idx == -1)
        return "";

    return s.substr(idx, minLength);
}

int main(){
    string s = "timetopractice";
    string p = "toc";

    cout << minWindow(s, p) << endl;

    return 0;
}


