        while (low <= high) {
            int mid = (low + high) / 2;

            if (isValid(s, p, mid, start)) {
                minLength = mid;
                high = mid - 1;
            }
            else {
                low = mid + 1;
            }
        }

        if (minLength == Integer.MAX_VALUE)
            return "";

        return s.substring(start[0], start[0] + minLength);
